"""Esquemas vectoriales propios. No representan planos de fabricación ni cotas reales."""
SVG_START='''<svg xmlns="http://www.w3.org/2000/svg" width="440" height="186" viewBox="0 0 440 186"><defs><linearGradient id="metal" x2="1" y2="1"><stop stop-color="#91a8b5"/><stop offset=".45" stop-color="#334c60"/><stop offset="1" stop-color="#172536"/></linearGradient><linearGradient id="gold" x2="0" y2="1"><stop stop-color="#70d8dc"/><stop offset="1" stop-color="#167b90"/></linearGradient></defs><rect width="440" height="186" rx="17" fill="#101d2c"/><path d="M0 155H440M0 35H440" stroke="#244052" stroke-width="1"/><path d="M10 175L430 10" stroke="#1a3245" stroke-width="1"/>'''
SVG_END='</svg>'

def dibujo(pieza):
    if pieza=='cuerpo':
        art='''<g stroke="#9bb3c3" stroke-width="3" stroke-linejoin="round"><path d="M40 69 H113 V40 H327 V69 H401 V125 H327 V152 H113 V125 H40 Z" fill="url(#metal)"/><rect x="100" y="63" width="240" height="65" rx="7" fill="#203b4a" stroke="#53d0d4" stroke-width="5"/><rect x="31" y="80" width="60" height="34" fill="#203b4a"/><rect x="350" y="80" width="60" height="34" fill="#203b4a"/><rect x="191" y="15" width="58" height="56" rx="6" fill="url(#metal)"/></g><path d="M115 95H325" stroke="#60e0d7" stroke-width="8" stroke-linecap="round"/><path d="M218 40V74" stroke="#ffbf71" stroke-width="7" stroke-linecap="round"/><g fill="#d7ecf2"><circle cx="60" cy="74" r="5"/><circle cx="60" cy="121" r="5"/><circle cx="377" cy="74" r="5"/><circle cx="377" cy="121" r="5"/></g>'''
    elif pieza=='bonete':
        art='''<g fill="url(#metal)" stroke="#a5bac8" stroke-width="3"><path d="M106 125L123 104H323L340 125V143H106Z"/><rect x="148" y="71" width="153" height="36" rx="8"/><path d="M174 71V45h101v26"/><rect x="208" y="17" width="33" height="47" rx="4" /></g><path d="M208 96h32" stroke="#57d4d7" stroke-width="8"/><path d="M114 119H334" stroke="#54c9cf" stroke-width="7"/><g fill="#deedf4" stroke="#1b3548" stroke-width="2"><circle cx="143" cy="127" r="9"/><circle cx="302" cy="127" r="9"/></g><path d="M222 5V32" stroke="#ffb86b" stroke-width="5"/>'''
    elif pieza=='espárragos':
        art='''<g transform="translate(25 0) rotate(-15 195 90)"><rect x="72" y="62" width="296" height="43" rx="8" fill="url(#metal)" stroke="#a5bac8" stroke-width="3"/><g stroke="#c9dce3" stroke-width="2">'''+''.join(f'<path d="M{x} 64l-14 39"/>' for x in range(96,365,16))+'''</g><rect x="155" y="55" width="126" height="57" fill="#223747" stroke="#64d2d5" stroke-width="3"/></g>'''
    else:
        art='''<g transform="translate(100 0)"><path d="M83 30L178 30L224 80L178 131L83 131L36 80Z" fill="url(#metal)" stroke="#c8d6df" stroke-width="5"/><ellipse cx="130" cy="80" rx="48" ry="42" fill="#142839" stroke="#63d5d8" stroke-width="6"/><g stroke="#b9d2db" stroke-width="3">'''+''.join(f'<path d="M{102+i*9} 50L{110+i*9} 108"/>' for i in range(7))+'''</g><ellipse cx="130" cy="80" rx="39" ry="33" fill="none" stroke="#6ca1a9" stroke-width="2"/></g>'''
    return (SVG_START+art+SVG_END).encode('utf-8')
